# Combine modeled residual time series generated by multiple model runs.
#
# The script searches result folders matching a specific naming pattern, reads
# each serie_residual_completada.csv file, extracts the modeled residual values,
# and merges all periods into a single chronological CSV file.
#
# Input:
# - Folders named as: resultados_modelo_era5_losangeles_merged_YYYY_YYYY
# - Each folder must contain: serie_residual_completada.csv
#
# Output:
# - CW_LA_RESIDUAL_MODEL.csv with the complete modeled residual series

import pandas as pd
from pathlib import Path
import re

root = Path("../[7].MODEL/LOSANGELES")
patron = re.compile(r"^resultados_modelo_era5_losangeles_merged_\d{4}_\d{4}$")

partes = []

for carpeta in sorted(root.iterdir()):
    if not carpeta.is_dir():
        continue
    if not patron.match(carpeta.name):
        continue

    archivo = carpeta / "serie_residual_completada.csv"
    if not archivo.exists():
        print("Saltando (no existe):", archivo)
        continue

    print("Leyendo:", archivo)

    df = pd.read_csv(archivo)

    df = df[["Anio", "Mes", "Dia", "Hora", "ResidualModelado"]].copy()
    df["ResidualModelado"] = pd.to_numeric(df["ResidualModelado"], errors="coerce")

    partes.append(df)

if len(partes) == 0:
    raise FileNotFoundError(
        "No se encontró ningún 'serie_residual_completada.csv' en carpetas tipo "
        "'resultados_modelo_era5_losangeles_merged_YYYY_YYYY' dentro de: "
        f"{root.resolve()}"
    )

df_residual = pd.concat(partes, ignore_index=True)

df_residual = df_residual.sort_values(["Anio", "Mes", "Dia", "Hora"])
df_residual = df_residual.drop_duplicates(
    subset=["Anio", "Mes", "Dia", "Hora"],
    keep="last"
)

salida = Path("CW_LA_RESIDUAL_MODEL.csv")
df_residual.to_csv(salida, index=False, na_rep="NaN")

print("Archivo generado:", salida)